export function used() {
  const parts = [];
  for (let i = 1; i <= 5; i++) {
    const squared = i * i;
    const label = `item-${i}`;
    parts.push({ label, squared, even: squared % 2 === 0 });
  }
  const total = parts.reduce((sum, p) => sum + p.squared, 0);
  const evens = parts.filter((p) => p.even).length;
  return { total, evens, count: parts.length };
}

export function unusedDyn() {
  const registry = new Map();
  const names = ['alpha', 'beta', 'gamma', 'delta'];
  for (const name of names) {
    const code = name
      .split('')
      .map((c) => c.charCodeAt(0))
      .reduce((a, b) => a + b, 0);
    registry.set(name, { code, upper: name.toUpperCase() });
  }
  const codes = [...registry.values()].map((v) => v.code);
  const max = Math.max(...codes);
  const min = Math.min(...codes);
  return { size: registry.size, max, min, spread: max - min };
}
